/*
 * jconfigint.h
 *
 * This file is normally generated by libjpeg-turbo's CMake build.  It is
 * checked in here so that the library can be built with SwiftPM, which does
 * not run CMake before compiling a C target.
 *
 * Unlike the generated file, the compiler-specific definitions below are
 * derived from compiler predefined macros so that the package remains
 * portable.
 */

#ifndef LIBJPEGTURBO_JCONFIGINT_H
#define LIBJPEGTURBO_JCONFIGINT_H

/* libjpeg-turbo build number */
#define BUILD  "swiftpm"

/* How to hide global symbols. */
#if defined(_MSC_VER)
#define HIDDEN
#elif defined(__GNUC__) || defined(__clang__)
#define HIDDEN  __attribute__((visibility("hidden")))
#else
#define HIDDEN
#endif

/* Compiler's inline keyword */
#undef inline

/* How to obtain function inlining. */
#if defined(_MSC_VER)
#define INLINE  __forceinline
#elif defined(__GNUC__) || defined(__clang__)
#define INLINE  __inline__ __attribute__((always_inline))
#else
#define INLINE  inline
#endif

/* How to obtain thread-local storage */
#if defined(_MSC_VER)
#define THREAD_LOCAL  __declspec(thread)
#elif defined(__GNUC__) || defined(__clang__)
#define THREAD_LOCAL  __thread
#else
#define THREAD_LOCAL
#endif

/* Define to the full name of this package. */
#define PACKAGE_NAME  "libjpeg-turbo"

/* Version number of package */
#define VERSION  "3.2.2"

/* The size of `size_t', as computed by sizeof. */
#if defined(__SIZEOF_SIZE_T__)
#define SIZEOF_SIZE_T  __SIZEOF_SIZE_T__
#elif defined(_WIN64) || defined(__LP64__) || defined(_LP64)
#define SIZEOF_SIZE_T  8
#else
#define SIZEOF_SIZE_T  4
#endif

/* Define if your compiler has __builtin_ctzl() and
   sizeof(unsigned long) == sizeof(size_t). */
#if (defined(__GNUC__) || defined(__clang__)) && \
    defined(__SIZEOF_LONG__) && defined(__SIZEOF_SIZE_T__) && \
    (__SIZEOF_LONG__ == __SIZEOF_SIZE_T__)
#define HAVE_BUILTIN_CTZL
#endif

/* Define to 1 if you have the <intrin.h> header file. */
#if defined(_MSC_VER)
#define HAVE_INTRIN_H
#endif

#if defined(_MSC_VER) && defined(HAVE_INTRIN_H)
#if (SIZEOF_SIZE_T == 8)
#define HAVE_BITSCANFORWARD64
#elif (SIZEOF_SIZE_T == 4)
#define HAVE_BITSCANFORWARD
#endif
#endif

#if defined(__has_attribute)
#if __has_attribute(fallthrough)
#define FALLTHROUGH  __attribute__((fallthrough));
#else
#define FALLTHROUGH
#endif
#else
#define FALLTHROUGH
#endif

/*
 * Define BITS_IN_JSAMPLE as either
 *   8   for 8-bit sample values (the usual setting)
 *   12  for 12-bit sample values
 *   16  for 16-bit sample values
 * Only 8, 12, and 16 are legal data precisions for JPEG according to the JPEG
 * standard, and the IJG code does not support anything else!
 */

#ifndef BITS_IN_JSAMPLE
#define BITS_IN_JSAMPLE  8      /* use 8, 12, or 16 */
#endif

#undef C_ARITH_CODING_SUPPORTED
#undef D_ARITH_CODING_SUPPORTED
#undef WITH_SIMD

#if BITS_IN_JSAMPLE == 8

/* Support arithmetic encoding */
#define C_ARITH_CODING_SUPPORTED 1

/* Support arithmetic decoding */
#define D_ARITH_CODING_SUPPORTED 1

/*
 * Use accelerated SIMD routines.  The SwiftPM build currently only compiles
 * the 64-bit Arm Neon implementation (libjpeg-turbo's x86 implementations are
 * written in NASM and cannot be assembled by SwiftPM).
 */
#if (defined(__aarch64__) || defined(_M_ARM64)) && !defined(WITH_SIMDE)
#define WITH_SIMD 1
#define SIMD_ARCHITECTURE  ARM64
#endif

#endif /* BITS_IN_JSAMPLE == 8 */

#endif /* LIBJPEGTURBO_JCONFIGINT_H */
